                m_rt = len(rt)
                best_local = None
                for pos in range(m_rt + 1):
                    a2 = rt[pos - 1] if pos - 1 >= 0 else depot
                    b2 = rt[pos] if pos < m_rt else depot
                    delta = (d(a2, u) + d(u, b2)) - d(a2, b2)
                    if best_local is None or delta < best_local[0]:
                        best_local = (delta, pos)
                if best_local is not None:
                    if best is None or best_local[0] < best[0]:
                        best = (best_local[0], ri, best_local[1])
            if best is None:
                # If no feasible insertion exists (shouldn't), create a new route.
                routes.append([u])
                routes_dem.append(dem_u)
            else:
                _, ri, pos = best
                routes[ri] = routes[ri][:pos] + [u] + routes[ri][pos:]
                routes_dem[ri] += dem_u

    # De-duplicate deterministically (keep first occurrence)
    seen = set()
    cleaned = []
    for rt in routes:
        nr = []
        for u in rt:
            if u not in seen:
                nr.append(u)
                seen.add(u)
        if nr:
            cleaned.append(nr)
    # Add back any customers missing after dedup
    missing2 = [u for u in customers if u not in seen]
    for u in missing2:
        cleaned.append([u])
        seen.add(u)
    routes = cleaned

    # ---- Intra-route local search ----
    for idx in range(len(routes)):
        if route_demand(routes[idx]) <= cap:
            routes[idx] = apply_2opt(routes[idx])

    # ---- Inter-route repair/improvement: relocate best-improvement ----
    routes = relocate_best_improvement(routes)

    # Final ensure capacity and include all customers
    routes = [r for r in routes if r]
    final_present = set()
    for r in routes:
        for u in r:
            final_present.add(u)
    if len(final_present) != len(customers):
        # last resort: rebuild routes as singleton for missing customers
        missing3 = [u for u in customers if u not in final_present]
        for u in missing3:
            routes.append([u])

    return routes
